const merged = [...list1, ...list2, ...list3, ...list4, ...listGlobal];
const uniqueMap = new Map<string, { title: string; artist: string; film: string; youtubeId?: string; startSeconds?: number; isSpatial?: boolean; isGlobal?: boolean }>();

for (const t of merged) {
  const key = `${t.title.toLowerCase()} - ${t.artist.toLowerCase()}`;
  if (!uniqueMap.has(key)) {
    uniqueMap.set(key, t);
  }
}

// Convert unique map entries to the rawTracks array, preserving youtubeId, startSeconds, and isSpatial fields
// All tracks on this site are 16D audio — mark every track as spatial
const rawTracks: Track[] = Array.from(uniqueMap.values()).map((track, idx) => ({
  id: idx + 1,
  title: track.title,
  artist: track.artist,
  film: track.film,
  youtubeId: track.youtubeId,
  startSeconds: track.startSeconds,
  isSpatial: track.isSpatial ?? (track.isGlobal ? false : true),
  isGlobal: track.isGlobal ?? false,
}));

// Fisher-Yates Shuffle function to randomize track order dynamically on load and assign clean sequential IDs (1 to length)
function shuffleAndReindex(array: Track[]): Track[] {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr.map((track, index) => ({
    ...track,
    id: index + 1,
  }));
}

// Export the dynamically shuffled and sequential re-indexed tracks
export const tracks: Track[] = shuffleAndReindex(rawTracks);

export function getRandomDuration(): number {
  return Math.floor(Math.random() * 120) + 180;
}
